43	template <typename T>
44	class AutoFuseConfigValue {
45	 public:
46	  AutoFuseConfigValue(const T &&t, const std::vector<T> &&valid_range) : default_val_(t), valid_range_(valid_range) {}
47	  Status SetVal(const T &t) {
48	    bool valid = false;
49	    GE_ASSERT_SUCCESS(IsValid(t, valid));
50	    if (valid) {
51	      val_ = t;
52	    } else {
53	      val_ = default_val_;
54	    }
55	    return af::SUCCESS;
56	  }
57	  T GetVal() const {
58	    return val_;
59	  }
60	  Status IsValid(const T &input, bool &is_valid) {
61	    if constexpr (std::is_integral_v<T>) {
62	      constexpr int32_t kRangeSize = 2;
63	      GE_ASSERT_TRUE(valid_range_.size() == kRangeSize,
64	                     "Error: valid_range must have exactly two elements for int type.");
65	      int min_val = std::min(valid_range_[0], valid_range_[1]);
66	      int max_val = std::max(valid_range_[0], valid_range_[1]);
67	      is_valid = (input >= min_val) && (input <= max_val);
68	    } else if constexpr (std::is_same_v<T, std::string>) {
69	      if (valid_range_.empty()) {  // 未设置范围表示无范围约束
70	        is_valid = true;
71	        return af::SUCCESS;
72	      }
73	      is_valid = std::find(valid_range_.begin(), valid_range_.end(), input) != valid_range_.end();
74	    }
75	    return af::SUCCESS;
76	  }
77	
78	 private:
79	  T val_;
80	  T default_val_;
81	  std::vector<T> valid_range_;
82	};
