122	  std::string force_tiling_case;                     // 强制选择的tiling case
123	  int64_t force_schedule_result{-1L};                // 强制选择的schedule result
124	  std::string force_template_op_name;                // 指定强制模板选择的op名
125	  std::string enable_small_shape_strategy{"false"};  // 是否开启小shape快速求解策略(false:不开启，true:开启)
126	  int64_t ub_threshold{20};  // ub利用率阈值，百分比，范围0-100，如果超过阈值，考虑多核和ub平衡
127	  int64_t corenum_threshold{40};  // 核数利用率阈值，百分比，范围0-100，如果超过少于阈值，ub停止增加，平衡多核占用
128	  std::string enable_multicore_ub_tradeoff{"false"};  // 是否开启多核ub权衡(false:不开启，true:开启)
129	  std::string att_profiling{"false"};                 // 是否开启att profiling(false:不开启，true:开启)
