164	// Dump 配置结构体
165	struct DumpConfig {
166	  bool enabled = false;
167	  std::string debug_dir;
168	};
169	
170	// 去除字符串两端空白
171	std::string TrimParam(const std::string &s) {
172	  size_t start = s.find_first_not_of(" \t");
173	  if (start == std::string::npos) return "";
174	  size_t end = s.find_last_not_of(" \t");
175	  return s.substr(start, end - start + 1);
176	}
177	
178	// 解析 debug_dir 参数值，去除引号
179	std::string ParseDebugDirValue(const std::string &value, bool has_space) {
180	  std::string dir = value;
181	  if (has_space) {
182	    // 去除可能的引号和空格
183	    dir.erase(0, dir.find_first_not_of(" \t\"'"));
184	    dir.erase(dir.find_last_not_of(" \t\"'") + 1);
185	  } else {
186	    // 去除可能的引号
187	    if (!dir.empty() && (dir.front() == '"' || dir.front() == '\'')) {
188	      dir.erase(0, 1);
189	    }
190	    if (!dir.empty() && (dir.back() == '"' || dir.back() == '\'')) {
191	      dir.pop_back();
192	    }
193	  }
194	  return dir;
195	}
196	
197	// 尝试从参数中解析 debug_dir
198	bool TryParseDebugDir(const std::string &param, std::string &debug_dir) {
199	  const char *patterns[] = {"debug_dir=", "debug_dir ="};
200	  for (size_t i = 0; i < 2; ++i) {
201	    size_t pos = param.find(patterns[i]);
202	    if (pos != std::string::npos) {
203	      std::string dir = ParseDebugDirValue(param.substr(pos + strlen(patterns[i])), i == 1);
204	      if (!dir.empty()) {
205	        debug_dir = dir;
206	        GELOGI("[DumpGraph] Found debug_dir in AUTOFUSE_DFX_FLAGS: %s", dir.c_str());
207	        return true;
208	      }
209	    }
210	  }
211	  return false;
212	}
213	
214	// 检查参数是否包含 codegen_compile_debug=true
215	bool IsCodegenCompileDebugEnabled(const std::string &param) {
216	  return param.find("codegen_compile_debug=true") != std::string::npos ||
217	         param.find("codegen_compile_debug = true") != std::string::npos;
218	}
219	
220	// 解析 AUTOFUSE_DFX_FLAGS 环境变量
221	DumpConfig ParseDfxFlags(const char *dfx_flags) {
222	  DumpConfig cfg;
223	  if (dfx_flags == nullptr || strlen(dfx_flags) == 0) {
224	    return cfg;
225	  }
226	
227	  std::string flags(dfx_flags);
228	  std::stringstream ss(flags);
229	  std::string param;
230	
231	  while (std::getline(ss, param, ';')) {
232	    param = TrimParam(param);
233	    if (param.empty()) continue;
234	
235	    if (!cfg.enabled && IsCodegenCompileDebugEnabled(param)) {
236	      cfg.enabled = true;
237	    }
238	    if (cfg.debug_dir.empty() && TryParseDebugDir(param, cfg.debug_dir)) {
239	      continue;
240	    }
241	  }
242	  return cfg;
243	}
244	
245	DumpConfig GetDumpConfig() {
246	  return ParseDfxFlags(std::getenv("AUTOFUSE_DFX_FLAGS"));
247	}
248	
249	std::string GetCodegenCompileDebugDir() {
250	  return GetDumpConfig().debug_dir;
